        uint32_t cur_cycle = DWT_GetCycle();
        if((cur_cycle - last_interrupt_cycle) > DEBOUNCE_CYCLES)
        {
            last_interrupt_cycle = cur_cycle;
            Gear_Shift();
        }
    }
}
/* USER CODE END 0 */
int main(void)
{
  HAL_Init();
  SystemClock_Config();
  MX_GPIO_Init();
  /* USER CODE BEGIN 2 */
  DWT_Init();
  LED_Update(current_gear);
  /* USER CODE END 2 */
  while (1)
  {
    /* USER CODE BEGIN 3 */
    HAL_Delay(10);
    /* USER CODE END 3 */
  }
}
