四、软件设计与实现（30分）
4.1 核心代码流程图
系统上电 → 系统时钟初始化（168MHz）→ GPIO、中断、DWT模块初始化 → 初始化默认档位为P档，更新LED显示 → 进入主循环等待中断
按键按下 → PE4触发外部中断 → 进入中断回调函数 → 读取DWT计数值，判断时间差是否满足50ms消抖要求
- 不满足：判定为按键抖动，直接退出；
- 满足：更新计时值，调用档位切换函数完成状态转移，调用LED更新函数刷新灯光状态 → 中断结束，返回主循环。
4.2 关键代码片段及注释
// 1. 定义档位枚举类型与全局变量
typedef enum {
    GEAR_P = 0,   // 停车档
    GEAR_R,       // 倒车档
    GEAR_N,       // 空档
    GEAR_D        // 前进档
} GearState;
volatile GearState current_gear = GEAR_P;   // 当前档位，上电默认P档
static uint32_t last_interrupt_cycle = 0;   // 记录上一次有效按键的DWT计数值
// 50ms消抖对应的时钟周期，主频168MHz
#define DEBOUNCE_CYCLES  (168000000 / 20)
// 2. DWT计数器初始化
static void DWT_Init(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk; // 使能DWT调试单元
    DWT->CYCCNT = 0;                                // 清零计数器
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;            // 开启时钟计数
}
// 读取当前DWT计数值
static uint32_t DWT_GetCycle(void)
{
    return DWT->CYCCNT;
}
// 3. LED状态更新函数（低电平点亮）
static void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P:  // P档：LED0亮，LED1灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_R:  // R档：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N:  // N档：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D:  // D档：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        default:
            break;
    }
}
// 4. 档位状态切换函数 P→R→N→D→P 循环
static void Gear_Shift(void)
{
    switch(current_gear)
    {
        case GEAR_P: current_gear = GEAR_R; break;
        case GEAR_R: current_gear = GEAR_N; break;
        case GEAR_N: current_gear = GEAR_D; break;
        case GEAR_D: current_gear = GEAR_P; break;
        default: current_gear = GEAR_P; break;
    }
    LED_Update(current_gear); // 切换档位后同步更新LED
}
// 5. 外部中断回调函数（按键消抖+档位切换）
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == GPIO_PIN_4) // 判断为按键PE4中断
    {
        uint32_t current_cycle = DWT_GetCycle();
        // 时间差大于50ms，判定为有效按键
        if((current_cycle - last_interrupt_cycle) > DEBOUNCE_CYCLES)
        {
            last_interrupt_cycle = current_cycle;
            Gear_Shift();
        }
    }
}
4.3 中断服务程序说明 
1. 配置方法
将PE4配置为 GPIO_MODE_IT_FALLING （下降沿外部中断）、内部上拉输入；在NVIC中使能EXTI4中断通道，配置中断优先级；由STM32CubeMX自动生成底层初始化代码。
2. 触发条件
硬件层面：按键按下，PE4引脚电平由高变低，产生下降沿；
软件层面：中断已使能，且相邻两次中断间隔超过50ms（消抖生效），才判定为有效触发。
3. 处理逻辑
外部中断触发后，进入统一中断入口函数，清除中断标志位后调用HAL库回调函数；在回调函数中读取DWT计数值做消抖判断，有效按键则执行档位切换与LED刷新，抖动信号直接丢弃。中断内仅执行简短逻辑，保证系统实时性。
