typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D
} GearState;
volatile GearState current_gear = GEAR_P;
static uint32_t last_interrupt_cycle = 0;
#define DEBOUNCE_CYCLES  (168000000 / 20)  // 50ms消抖周期
/* USER CODE END PV */
/* USER CODE BEGIN 0 */
// DWT计数器初始化
void DWT_Init(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
// 读取DWT计数值
uint32_t DWT_GetCycle(void)
{
    return DWT->CYCCNT;
}
// LED状态更新函数
void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_R:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D:
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        default: break;
    }
}
// 档位切换函数
void Gear_Shift(void)
{
    switch(current_gear)
    {
        case GEAR_P: current_gear = GEAR_R; break;
        case GEAR_R: current_gear = GEAR_N; break;
        case GEAR_N: current_gear = GEAR_D; break;
        case GEAR_D: current_gear = GEAR_P; break;
        default: current_gear = GEAR_P; break;
    }
    LED_Update(current_gear);
}
// 外部中断回调函数
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == GPIO_PIN_4)
    {
        uint32_t cur_cycle = DWT_GetCycle();
        if((cur_cycle - last_interrupt_cycle) > DEBOUNCE_CYCLES)
        {
            last_interrupt_cycle = cur_cycle;
            Gear_Shift();
        }
    }
}
