六、核心代码实现
1.档位状态定义
c
typedef enum {
    GEAR_P,
    GEAR_R,
    GEAR_N,
    GEAR_D
} GearState;
volatile GearState gear = GEAR_P;
2.LED状态更新函数
c
static void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P: // P档：LED0亮，LED1灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_R: // R档：LED0灭，LED1亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        case GEAR_N: // N档：两灯全灭
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_SET);
            break;
        case GEAR_D: // D档：两灯全亮
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_9, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF, GPIO_PIN_10, GPIO_PIN_RESET);
            break;
        default:
            break;
    }
}
3. DWT消抖与中断回调函数
c
#define DEBOUNCE_CYCLES (168000000 / 20) // 50ms消抖周期（168MHz时钟）
static uint32_t last_interrupt_cycle = 0;
// DWT计数器初始化
static void DWT_Init(void)
{
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    DWT->CYCCNT = 0;
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
// 档位切换函数
static void Gear_Shift(void)
{
    switch(gear)
    {
        case GEAR_P: gear = GEAR_R; break;
        case GEAR_R: gear = GEAR_N; break;
        case GEAR_N: gear = GEAR_D; break;
        case GEAR_D: gear = GEAR_P; break;
        default: break;
    }
    LED_Update(gear);
}
// 外部中断回调函数
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == GPIO_PIN_4) // 检测KEY0按键
    {
        uint32_t current_cycle = DWT->CYCCNT;
        // 判断两次中断间隔是否大于消抖周期
        if((current_cycle - last_interrupt_cycle) > DEBOUNCE_CYCLES)
        {
            last_interrupt_cycle = current_cycle;
            Gear_Shift(); // 执行档位切换
        }
    }
}
