/* main.c - 汽车档位模拟器核心代码 */
#include "main.h"
#include "gpio.h"
/* 1. 档位枚举定义 */
typedef enum {
    GEAR_P = 0,
    GEAR_R,
    GEAR_N,
    GEAR_D
} GearState;
/* 2. 全局变量 */
volatile GearState currentGear = GEAR_P;  // 当前档位
static uint32_t lastTick = 0;              // 上次按键的DWT计数值
static const uint32_t DEBOUNCE_TIME_CYCLES = 168000000 * 0.05; // 50ms对应168MHz下的周期数：8,400,000
/* 3. 函数声明 */
static void DWT_Init(void);
static void LED_Update(GearState state);
static void Gear_Shift(void);
/* 4. DWT初始化 */
static void DWT_Init(void) {
    // 使能DWT跟踪单元
    CoreDebug->DEMCR |= CoreDebug_DEMCR_TRCENA_Msk;
    // 复位计数器
    DWT->CYCCNT = 0;
    // 使能计数器
    DWT->CTRL |= DWT_CTRL_CYCCNTENA_Msk;
}
/* 5. LED显示更新 */
static void LED_Update(GearState state) {
    switch(state) {
        case GEAR_P:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET); // 亮
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);    // 灭
            break;
        case GEAR_R:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
        case GEAR_N:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_SET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_SET);
            break;
        case GEAR_D:
            HAL_GPIO_WritePin(LED0_GPIO_Port, LED0_Pin, GPIO_PIN_RESET);
            HAL_GPIO_WritePin(LED1_GPIO_Port, LED1_Pin, GPIO_PIN_RESET);
            break;
    }
}
/* 6. 档位切换逻辑（状态机） */
static void Gear_Shift(void) {
    currentGear = (currentGear + 1) % 4; // 循环切换 P->R->N->D->P
    LED_Update(currentGear);
    // 【选做部分】串口输出档位信息
    char* gearName[] = {"P", "R", "N", "D"};
    printf("Gear switched to: %s\r\n", gearName[currentGear]);
}
/* 7. 中断回调函数（核心消抖逻辑） */
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin) {
    if(GPIO_Pin == KEY0_Pin) {
        uint32_t currentTick = DWT->CYCCNT; // 获取当前时刻
        // 检查与上次按键的时间差是否大于消抖阈值
        if((currentTick - lastTick) > DEBOUNCE_TIME_CYCLES) {
            lastTick = currentTick;      // 更新上次按键时间
            Gear_Shift();                // 执行档位切换
        }
    }
}
