四、软件设计与实现（30分）
4.1 核心代码流程图
系统上电初始化→GPIO、EXTI、DWT初始化→默认P档位、刷新LED→等待按键中断→DWT时间校验消抖→有效按键执行档位切换→更新LED显示，循环运行。挡位流转：P→R→N→D→P。
4.2 关键代码片段及注释
#include "main.h"
typedef enum {
    GEAR_P = 0, //停车挡
    GEAR_R,     //倒车挡
    GEAR_N,     //空挡
    GEAR_D      //前进挡
} GearState;
volatile GearState gear = GEAR_P;
#define DEBOUNCE_CYCLES 8400000U //50ms计数周期
uint32_t last_tick=0;
//LED档位显示刷新函数
void LED_Update(GearState state)
{
    switch(state)
    {
        case GEAR_P: //LED0亮、LED1灭
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);break;
        case GEAR_R: //LED0灭、LED1亮
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
        case GEAR_N: //双灯熄灭
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);break;
        case GEAR_D: //双灯点亮
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
    }
}
//挡位切换
void Gear_Shift(void)
{
    gear++;
    if(gear>GEAR_D) gear=GEAR_P;
    LED_Update(gear);
}
//中断回调+DWT消抖
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == KEY0_Pin)
    {
        uint32_t now=DWT_GetCycle();
        if((now-last_tick)>DEBOUNCE_CYCLES)
        {
            last_tick=now;
            Gear_Shift();
        }
    }
}
4.3 中断服务程序说明
CubeMX配置PE4为EXTI4下降沿中断，在NVIC中配置优先级并使能中断；按键下降沿触发硬件中断，进入HAL库统一回调函数，函数内只做时间判断与挡位切换，无延时等耗时代码，保证中断实时响应。
