            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);break;
        case GEAR_R:
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
        case GEAR_N:
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_SET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_SET);break;
        case GEAR_D:
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_9,GPIO_PIN_RESET);
            HAL_GPIO_WritePin(GPIOF,GPIO_PIN_10,GPIO_PIN_RESET);break;
    }
}
void Gear_Shift(void)
{
    gear++;
    if(gear>GEAR_D) gear=GEAR_P;
    LED_Update(gear);
}
void HAL_GPIO_EXTI_Callback(uint16_t GPIO_Pin)
{
    if(GPIO_Pin == KEY0_Pin)
    {
        uint32_t now=DWT_GetCycle();
        if((now-last_tick)>DEBOUNCE_CYCLES)
        {
            last_tick=now;
            Gear_Shift();
        }
    }
}
int main(void)
{
    HAL_Init();
    SystemClock_Config();
    MX_GPIO_Init();
    DWT_Init();
    LED_Update(gear);
    while(1){}
}
